using namespace beefiscal::idf;
namespace beefiscal::idf{esp_err_t canonical_cbor_to_json(const uint8_t*,size_t,cJSON**){return ESP_ERR_NOT_SUPPORTED;}}
static std::string text(cJSON*v,const char*k){auto*x=cJSON_GetObjectItemCaseSensitive(v,k);assert(cJSON_IsString(x));return x->valuestring;}
static std::string scalar(const char*p,const char*q){sqlite3*d{};sqlite3_stmt*s{};assert(sqlite3_open(p,&d)==0);assert(sqlite3_prepare_v2(d,q,-1,&s,nullptr)==0);assert(sqlite3_step(s)==SQLITE_ROW);const auto*t=sqlite3_column_text(s,0);std::string out=t?(const char*)t:"";sqlite3_finalize(s);sqlite3_close(d);return out;}
static std::string expected_unp,expected_server,expected_surrogate;static bool expected_mqtt=false;
struct Exec:ReceiptExecutor{int calls{};bool ready()override{return true;}ExecutionResult execute(const ReceiptPlan&p)override{++calls;assert(p.authorization_verified==!expected_mqtt);assert(p.operator_code=="A001");assert(p.unp==expected_unp);assert(p.server_sale_id==expected_server);assert(p.client_sale_surrogate_id==expected_surrogate);assert(p.payments.size()==1&&p.payments[0].amount_minor==250);return{ExecutionCertainty::Committed,"470","","","",""};}ExecutionResult recover(const RecoveryItem&)override{assert(false);return{};}};
int main(int argc,char**argv){assert(argc==6);expected_mqtt=std::string(argv[4])=="mqtt-valid";std::ifstream in(argv[1]);std::stringstream bytes;bytes<<in.rdbuf();auto*f=cJSON_Parse(bytes.str().c_str());assert(f);auto*c=cJSON_GetObjectItem(f,"command");auto*b=cJSON_GetObjectItem(f,"binding");auto*server=cJSON_GetObjectItem(expected_mqtt?cJSON_GetObjectItem(c,"payload"):c,"server_sale_id");expected_server=cJSON_IsString(server)?server->valuestring:"";auto*surrogate=cJSON_GetObjectItem(c,"client_sale_surrogate_id");expected_surrogate=cJSON_IsString(surrogate)?surrogate->valuestring:"";expected_unp=expected_server.empty()?"AB123456-A001-0000001":text(cJSON_GetObjectItem(c,expected_mqtt?"payload":"canonical_payload"),"unp");auto*ae=cJSON_GetObjectItem(cJSON_GetObjectItem(f,"acceptance_event"),"payload");ae=cJSON_GetObjectItem(ae,"acceptance_evidence");CompositeBinding binding;binding.tenant_id=text(b,"tenant_id");binding.location_id=text(b,"location_id");binding.register_id=text(b,"register_id");binding.edge_device_id=text(b,"edge_device_id");binding.generation=cJSON_GetObjectItem(b,"generation")->valuedouble;binding.payload_sha256=text(ae,"binding_sha256");binding.fiscal.device_id=text(cJSON_GetObjectItem(b,"fiscal_endpoint"),"device_id");binding.fiscal.fiscal_device_number=text(cJSON_GetObjectItem(b,"fiscal_endpoint"),"fiscal_device_number");binding.fiscal.fiscal_memory_number=text(cJSON_GetObjectItem(b,"fiscal_endpoint"),"fiscal_memory_number");auto*a=cJSON_GetObjectItem(b,"operational_authority");binding.authority.unp_prefix=text(a,"unp_prefix");binding.authority.unp_range_start=cJSON_GetObjectItem(a,"unp_range_start")->valuedouble;binding.authority.unp_range_end=cJSON_GetObjectItem(a,"unp_range_end")->valuedouble;std::ifstream keyfile(argv[2]);std::stringstream keybytes;keybytes<<keyfile.rdbuf();auto pem=keybytes.str();auto kid=text(cJSON_GetObjectItem(f,"authorization"),"key_id");ExecutionAuthorizationTrust trust{pem.c_str(),kid.c_str(),(int64_t)cJSON_GetObjectItem(f,"now")->valuedouble};const std::string mode=argv[4];if(mode=="missing")cJSON_DeleteItemFromObject(c,"execution_authorization");else if(mode=="signature")cJSON_SetValuestring(cJSON_GetObjectItem(cJSON_GetObjectItem(c,"client_proof"),"signature"),"AAAA");else if(mode=="binding")binding.authority.unp_range_end--;else if(mode=="expired")trust.now+=1000;else if(mode=="payload")cJSON_SetValuestring(cJSON_GetObjectItem(cJSON_GetObjectItem(c,"canonical_payload"),"operator_code"),"A002");char*wire=cJSON_PrintUnformatted(c);remove(argv[3]);DurableStorage storage;assert(storage.open_database_for_test(argv[3])==ESP_OK);assert(storage.configure_authority(binding.authority.unp_prefix.c_str(),binding.authority.unp_range_start,binding.authority.unp_range_end,binding.generation)==ESP_OK);Exec exec;auto hmac=expected_mqtt?text(f,"command_hmac_key_base64"):"a2tra2tra2tra2tra2tra2tra2tra2tra2tra2tra2s=";CommandInstant mqtt_time;CommandClock mqtt_clock{[](CommandInstant&out,void*ctx){out=*static_cast<CommandInstant*>(ctx);return true;},&mqtt_time};if(expected_mqtt)assert(parse_command_instant(text(c,"issued_at"),mqtt_time));IntentProcessor processor(storage,binding,exec,hmac,nullptr,nullptr,&trust,expected_mqtt?&mqtt_clock:nullptr);auto rc=processor.accept({(const uint8_t*)wire,strlen(wire),expected_mqtt?Ingress::Mqtt:Ingress::Http});if(mode!="valid"&&mode!="mqtt-valid"){assert(rc!=ESP_OK);assert(exec.calls==0);assert(scalar(argv[3],"SELECT count(*) FROM operations")=="0");assert(scalar(argv[3],"SELECT next_unp FROM authority_state")=="1");}else{if(rc!=ESP_OK)std::cerr<<"accept rc="<<rc<<"\n";assert(rc==ESP_OK);assert(exec.calls==1);assert(processor.accept({(const uint8_t*)wire,strlen(wire),expected_mqtt?Ingress::Mqtt:Ingress::Http})==ESP_OK&&exec.calls==1);assert(scalar(argv[3],"SELECT next_unp FROM authority_state")==(expected_server.empty()?"2":"1"));auto accepted=scalar(argv[3],"SELECT payload FROM event_outbox WHERE event_id LIKE 'received-%'");if(accepted.empty())accepted=scalar(argv[3],"SELECT payload FROM event_outbox WHERE event_id LIKE 'received-%'");auto result=scalar(argv[3],"SELECT result_payload FROM operations");auto*r=cJSON_Parse(result.c_str());assert(r);assert(text(r,"unp")==expected_unp);auto*payment=cJSON_GetArrayItem(cJSON_GetObjectItem(r,"payment_evidence"),0);assert(text(payment,"state")=="FISCALIZED_CASH");std::ofstream out(argv[5]);out<<"{\"accepted\":"<<accepted<<",\"result\":"<<result<<"}";cJSON_Delete(r);}cJSON_free(wire);cJSON_Delete(f);std::cout<<mode<<" actual issuer→IntentProcessor→SQLite PASS\n";}
